RAILS_ENV=test bundle exec ruby -r ./spec/rails_helper -e '
  Sidekiq.testing!(:fake)
  # Warm up
  ActiveRecord::Base.transaction do
    Fabricate(:status)
    raise ActiveRecord::Rollback
  end

  def bench(name, n = 50)
    queries = []
    sub = ActiveSupport::Notifications.subscribe("sql.active_record") do |*, payload|
      next if payload[:name] == "SCHEMA"
      queries << payload[:sql]
    end
    t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
    ActiveRecord::Base.transaction do
      n.times { yield }
      raise ActiveRecord::Rollback
    end
    dt = Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0
    ActiveSupport::Notifications.unsubscribe(sub)
    puts format("%-28s %6.2fms/call   %4.1f queries/call", name, dt / n * 1000, queries.size.to_f / n)
    if n == 1
      queries.each_with_index { |q, i| puts "  #{i+1}. #{q[0, 140]}" }
    end
  end

  bench("account", 30) { Fabricate(:account) }
  bench("remote_account", 30) { Fabricate(:remote_account) }
  bench("account (user: nil)", 30) { Fabricate(:account, user: nil) }
  bench("user", 30) { Fabricate(:user) }
  bench("status", 30) { Fabricate(:status) }
  bench("status (existing acct)", 30) do
    @a ||= Fabricate(:account)
    Fabricate(:status, account: @a)
  end
  bench("custom_emoji", 10) { Fabricate(:custom_emoji) }
  bench("preview_card", 10) { Fabricate(:preview_card) }
  bench("accessible_access_token", 30) { Fabricate(:accessible_access_token) }
  puts "\n--- Single :account queries ---"
  bench("account (1)", 1) { Fabricate(:account) }
  puts "\n--- Single :user queries ---"
  bench("user (1)", 1) { Fabricate(:user) }
  puts "\n--- Single :status queries ---"
  bench("status (1)", 1) { Fabricate(:status) }
'

