  def t(label, n = 50)
    t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
    ActiveRecord::Base.transaction do
      n.times { yield }
      raise ActiveRecord::Rollback
    end
    dt = Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0
    puts format("%-42s %6.2fms/call", label, dt / n * 1000)
  end

  hash = User.new(password: "123456789").encrypted_password
  puts "Precomputed hash: #{hash}"

  t("BCrypt password= 123456789", 50) { User.new(password: "123456789") }
  t("Faker::Internet.user_name", 200) { Faker::Internet.user_name(separators: %w(_)) }
  t("Faker::Internet.email", 200) { Faker::Internet.email }
  t("Faker::Internet.ip_v4_address", 200) { Faker::Internet.ip_v4_address }
  t("Faker::Internet.user_agent", 200) { Faker::Internet.user_agent }
  t("Fabricate(:account)", 50) { Fabricate(:account) }
  t("Fabricate(:account, user: nil)", 50) { Fabricate(:account, user: nil) }
  t("Fabricate(:account, user: nil, keypairs: [])", 50) { Fabricate(:account, user: nil, keypairs: []) }
  t("Fabricate(:account, user: nil, legacy_keypair: true)", 50) { Fabricate(:account, user: nil, legacy_keypair: true) }
  t("Fabricate(:user) current", 50) { Fabricate(:user) }
  t("Fabricate(:user, password: nil, encrypted_password: hash)", 50) { Fabricate(:user, password: nil, encrypted_password: hash) }
  t("Fabricate(:login_activity, user: existing)", 50) do
