    Fabricate(:login_activity, user: @u)
  end
  t("Fabricate(:status) current", 30) { Fabricate(:status) }
  t("Fabricate.build(:account) (no save)", 50) { Fabricate.build(:account) }
  t("Fabricate.build(:account, user: nil) (no save)", 50) { Fabricate.build(:account, user: nil) }
'

